create or replace function public.rtw_record_human_check_choice(p_session_id uuid,p_player_id uuid,p_nonce uuid,p_choice integer) returns boolean language plpgsql security definer set search_path='' as $$ declare v_count integer; begin if auth.role()<>'service_role' then return false; end if; update private.rtw_human_checks c set chosen_at=now() where c.session_id=p_session_id and c.player_id=p_player_id and c.nonce=p_nonce and c.target=p_choice and c.status='pending' and c.chosen_at is null and now()>=c.due_at and now()<c.due_at+interval '10 seconds' and exists(select 1 from public.game_sessions s where s.id=c.session_id and s.user_id=p_player_id and s.status='active'); get diagnostics v_count=row_count; return v_count=1; end $$; revoke all on function public.rtw_record_human_check_choice(uuid,uuid,uuid,integer) from public,anon,authenticated; grant execute on function public.rtw_record_human_check_choice(uuid,uuid,uuid,integer) to service_role;;
